const item = $input.first().json.body || $input.first().json;

const totalFormatted = Number(item.totalAmount || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const cotas = Array.isArray(item.selectedNumbers) ? item.selectedNumbers.join(', ') : item.selectedNumbers;

const description = `👤 *Comprador:* ${item.customerName}\n` +
  `📱 *WhatsApp:* ${item.customerPhone}\n` +
  `🎫 *Cotas (${item.numbersCount}):* ${cotas}\n` +
  `💰 *Valor a conferir:* R$ ${totalFormatted}\n\n` +
  `🔑 *Chave PIX:* ${item.pixKey} (${item.pixName})\n\n` +
  `Confira no app do seu banco se o PIX caiu e clique no botão abaixo para aprovar ou cancelar.`;

return [{
  json: {
    ...item,
    totalFormatted,
    cotas,
    description,
    adminPhone: item.adminPhone || '556392917027'
  }
}];

